// RawXML 读取内嵌的原始 XML（不存在返回 nil）。
// 注意：它读到的是编译期内容，热更新后与运行中的快照不一致，仅用于比对与排障。
// 典型用途：线上版本与本地源码 diff、热更新前后内容比对。
func RawXML(name string) []byte {
	b, err := rawXML.ReadFile("embed/xml/" + name)
	if err != nil {
		return nil
	}
	return b
}

// LoadedTables 已加载配置表名（启动自检/日志用）
// 返回 append([]string(nil), tableNames...) 的防御性拷贝：直接返回 tableNames
// 会让调用方拿到内部切片的引用，一次 append 或赋值就可能污染全局表名单。
func LoadedTables() []string {
	return append([]string(nil), tableNames...)
}

// Summary 配置规模摘要
// 打一行日志回答「进程启动时加载了多少表、哪个版本」，线上排障第一眼信息。
func Summary() string {
	return fmt.Sprintf("gamedata: %d tables, version %s", len(tableNames), Version())
}
